import React from 'react';
import clsx from 'clsx';
import './AcidGlassFolder.css';

export interface AcidGlassFolderProps {
    icon?: React.ReactNode;
    title?: string;
    className?: string;
}

export const AcidGlassFolder = ({ icon, title, className }: AcidGlassFolderProps) => {
    return (
        <div className={clsx('ac-glass-folder-group', className)}>
            <div className="ac-glass-folder-container">
                {/* Top tab back */}
                <div className="ac-folder-back-tab"></div>

                {/* Back folder body */}
                <div className="ac-folder-back-body"></div>

                {/* Folder layers (Inner paper look) */}
                <div className="ac-folder-layer ac-layer-1"></div>
                <div className="ac-folder-layer ac-layer-2"></div>
                <div className="ac-folder-layer ac-layer-3"></div>

                {/* Front folder layer with icon */}
                <div className="ac-folder-front">
                    <div className="ac-folder-icon">{icon}</div>
                </div>
            </div>
            {title && <span className="ac-folder-label">{title}</span>}
        </div>
    );
};

.ac-glass-folder-group {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1.5rem;
    perspective: 1500px;
}

.ac-glass-folder-container {
    position: relative;
    width: 180px;
    height: 120px;
    cursor: pointer;
    transition: transform 0.3s ease;
}

.ac-glass-folder-container:hover {
    transform: translateY(-5px);
}

/* Back Tab */
.ac-folder-back-tab {
    position: absolute;
    top: -12px;
    left: 0;
    width: 60px;
    height: 20px;
    background: rgba(244, 67, 54, 0.15);
    /* Brand tint */
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-bottom: none;
    border-radius: 4px 4px 0 0;
}

/* Back Body */
.ac-folder-back-body {
    position: absolute;
    inset: 0;
    background: rgba(255, 255, 255, 0.03);
    backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 0 8px 8px 8px;
}

/* Middle Layers */
.ac-folder-layer {
    position: absolute;
    inset: 4px;
    background: rgba(255, 255, 255, 0.05);
    border-radius: 4px;
    transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    transform-origin: bottom;
}

.ac-glass-folder-container:hover .ac-layer-1 {
    transform: rotateX(-15deg);
}

.ac-glass-folder-container:hover .ac-layer-2 {
    transform: rotateX(-25deg);
}

.ac-glass-folder-container:hover .ac-layer-3 {
    transform: rotateX(-35deg);
}

/* Front Cover */
.ac-folder-front {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 90%;
    background: rgba(244, 67, 54, 0.1);
    /* Branded glass */
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 4px;
    transform-origin: bottom;
    transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.3s ease;
    display: flex;
    align-items: center;
    justify-content: center;
}

.ac-glass-folder-container:hover .ac-folder-front {
    transform: rotateX(-45deg);
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4);
}

.ac-folder-icon {
    color: var(--ac-text-primary);
    opacity: 0.8;
    transition: transform 0.4s ease;
}

.ac-glass-folder-container:hover .ac-folder-icon {
    transform: scale(1.1) translateY(-5px);
}

.ac-folder-label {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 700;
    color: var(--ac-text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.1em;
}
